import sys
import math
def is_pronic(n):
    if n < 0: return "false"
    r = math.isqrt(n)
    for x in (r-1, r, r+1):
        if x >= 0 and x * (x + 1) == n:
            return "true"
    return "false"
if __name__ == "__main__":
    n = int(sys.stdin.readline())
    print(is_pronic(n))

